UPDATE movies SET overview = 'Mitsuha - nữ sinh vùng nông thôn yên bình và Taki - nam sinh năng động ở Tokyo bất ngờ phát hiện họ bị hoán đổi thân xác trong giấc mơ. Khi bí mật về một thảm họa thiên thạch ập đến được hé lộ, cả hai bắt đầu cuộc hành trình vượt thời gian đầy kỳ diệu để tìm thấy nhau.' WHERE tmdb_id = 372058;

UPDATE movies SET overview = 'Cô bé Chihiro vô tình lạc vào thế giới linh hồn kỳ bí sau khi bố mẹ bị biến thành heo vì lòng tham. Để cứu gia đình và tìm đường trở về thế giới loài người, cô bé phải dũng cảm làm việc tại nhà tắm công cộng của phù thủy Yubaba đầy mưu mô.' WHERE tmdb_id = 129;

UPDATE movies SET overview = 'Dom Cobb là một đạo chích bậc thầy chuyên xâm nhập vào tiềm thức của mục tiêu trong lúc ngủ để đánh cắp những bí mật giá trị nhất. Anh được trao cơ hội chuộc lại cuộc đời tự do với một nhiệm vụ bất khả thi: cấy một ý tưởng vào tâm trí người khác thay vì đánh cắp nó.' WHERE tmdb_id = 27205;

