UPDATE movies SET overview = 'Câu chuyện lay động lòng người về Forrest Gump - một chàng trai có chỉ số IQ thấp nhưng sở hữu trái tim vàng lương thiện. Bằng sự chân thành và nghị lực phi thường, anh đã trải qua những cột mốc lịch sử vĩ đại của nước Mỹ và luôn một lòng hướng về tình yêu thời thơ ấu.' WHERE tmdb_id = 13;

UPDATE movies SET overview = 'Andy Dufresne - một nhân viên ngân hàng tài năng bị kết án oan vì tội sát hại vợ và nhân tình, chịu mức án chung thân tại nhà tù Shawshank khắc nghiệt. Trải qua gần hai thập kỷ với lòng kiên trì và niềm tin bất diệt vào tự do, anh đã tạo nên cuộc đào thoát ngoạn mục nhất lịch sử.' WHERE tmdb_id = 278;

