UPDATE movies SET overview = 'Bức tranh trần trụi về khu ổ chuột khét tiếng Cidade de Deus tại Rio de Janeiro thập niên 1960-1980. Hai cậu bé cùng lớn lên tại đây nhưng chọn hai ngã rẽ hoàn toàn trái ngược: một người trở thành nhiếp ảnh gia tài ba, người kia trở thành trùm ma túy tàn độc.' WHERE tmdb_id = 598;

